import os
import torch


class Config:
    """
    Configuration for the Pure-Feedback Dense-Refined Network (PF-DRN) - Idea 47.
    Defines project-wide constants, hyperparameters, and file paths.
    """

    # =========================================================================
    # Directories and Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_47"

    # Metadata Files (Generated by previous steps)
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Cache Directory for processed tensors
    CACHE_DIR = WORKING_DIR
    os.makedirs(CACHE_DIR, exist_ok=True)

    # Submission output
    SUBMISSION_PATH = "./submission/submission.csv"
    os.makedirs(os.path.dirname(SUBMISSION_PATH), exist_ok=True)

    # =========================================================================
    # Data Specifications
    # =========================================================================
    SEQ_LENGTH = 107
    SEQ_SCORED = 68

    # The complete list of target columns provided in the training data
    # Order matches sample_submission.csv columns (excluding id)
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_pH10", "deg_Mg_50C", "deg_50C"]

    # The subset of targets that are actually scored by the metric
    SCORED_TARGETS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]

    # Indices of the scored targets within the TARGET_COLS list
    # reactivity (0), deg_Mg_pH10 (1), deg_Mg_50C (3)
    SCORED_INDICES = [0, 1, 3]

    NUM_TARGETS = len(TARGET_COLS)

    # =========================================================================
    # Model Hyperparameters (PF-DRN)
    # =========================================================================
    # 1. Main Backbone (Static Dense Dilated TCN)
    BACKBONE_GROWTH_RATE = 64
    BACKBONE_DILATIONS = [1, 2, 4, 8, 16, 32]
    BACKBONE_KERNEL_SIZE = 3
    LATENT_DIM = 64  # Output dimension of the static backbone (Z)

    # 2. Pure-Feedback Module
    FEEDBACK_GROWTH_RATE = 16  # Low capacity as per Idea 47
    FEEDBACK_DILATIONS = [1, 2, 4]  # Lightweight receptive field
    FEEDBACK_DIM = 32  # Output dimension of feedback embeddings (E_fb)

    # 3. Aggregation (RNN)
    RNN_HIDDEN_SIZE = 64  # Compact size to match feature dimension
    RNN_LAYERS = 1
    RNN_BIDIRECTIONAL = True

    # General
    DROPOUT = 0.1

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    SEED = 42
    BATCH_SIZE = 32
    EPOCHS = 50
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4

    # Early Stopping
    PATIENCE = 10

    # Loss Weights (Iterative Refinement)
    PASS1_WEIGHT = 0.5
    PASS2_WEIGHT = 1.0

    # =========================================================================
    # Hardware
    # =========================================================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 2
